class Solution {
    public: int maxSumRangeQuery(vector<int>& nums,vector<vector<int>>& requests){
        int n=nums.size();
        vector<int> frequency(n+1);
        for(auto& request:requests){
            ++frequency[request[0]];
            --frequency[request[1]+1];
        }
        for(int i=1;i<n;++i)frequency[i]+=frequency[i-1];
        sort(nums.begin(),nums.end());
        sort(frequency.begin(),frequency.begin()+n);
        long long answer=0;
        for(int i=0;i<n;++i)answer=(answer+1LL*nums[i]*frequency[i])%1000000007;
        return answer;
    }
};
